insert into job (id, title, team, location, employment_type, pay, summary, responsibilities, requirements, status, sort_order, posted_at, updated_at) values ('senior-backend-engineer-spring-boot-remote-us', 'Senior Backend Engineer (Spring Boot)', 'Engineering', 'Remote (US)', 'Full-time', '$165k–$205k', 'Build the services behind the marketplace: catalogue, checkout, payments and delivery.', '["Design and ship features end to end with product and design", "Own services in production: on-call, SLOs and post-incident fixes", "Review code and raise the bar on testing and observability"]'::jsonb, '["5+ years building production backend systems", "Strong with distributed systems, SQL and event-driven design", "Clear written communication across time zones"]'::jsonb, 'OPEN', 0, '2026-09-15T00:00:00Z', '2026-09-15T00:00:00Z');
insert into job (id, title, team, location, employment_type, pay, summary, responsibilities, requirements, status, sort_order, posted_at, updated_at) values ('go-engineer-search-discovery-remote-us', 'Go Engineer, Search & Discovery', 'Engineering', 'Remote (US)', 'Full-time', '$160k–$200k', 'Build the services behind the marketplace: catalogue, checkout, payments and delivery.', '["Design and ship features end to end with product and design", "Own services in production: on-call, SLOs and post-incident fixes", "Review code and raise the bar on testing and observability"]'::jsonb, '["5+ years building production backend systems", "Strong with distributed systems, SQL and event-driven design", "Clear written communication across time zones"]'::jsonb, 'OPEN', 10, '2026-09-15T00:00:00Z', '2026-09-15T00:00:00Z');
insert into job (id, title, team, location, employment_type, pay, summary, responsibilities, requirements, status, sort_order, posted_at, updated_at) values ('product-designer-seller-experience-houston-tx', 'Product Designer, Seller Experience', 'Design', 'Houston, TX', 'Full-time', '$130k–$160k', 'Shape how sellers run their business on AfroTransact, from onboarding to payouts.', '["Lead research with sellers across communities", "Design flows, prototypes and production-ready specs", "Contribute to the design system"]'::jsonb, '["4+ years of product design for complex tools", "A portfolio showing research-driven work", "Accessibility (WCAG 2.2) know-how"]'::jsonb, 'OPEN', 20, '2026-09-15T00:00:00Z', '2026-09-15T00:00:00Z');
insert into job (id, title, team, location, employment_type, pay, summary, responsibilities, requirements, status, sort_order, posted_at, updated_at) values ('trust-safety-analyst-atlanta-ga', 'Trust & Safety Analyst', 'Operations', 'Atlanta, GA', 'Full-time', '$62k–$78k', 'Keep customers, sellers and the marketplace safe and well supported.', '["Investigate cases and resolve them within SLA", "Spot patterns and feed them into policy and tooling", "Document decisions clearly"]'::jsonb, '["2+ years in support, trust & safety or risk", "Calm, careful judgement", "Fluency in an additional language is a plus"]'::jsonb, 'OPEN', 30, '2026-09-15T00:00:00Z', '2026-09-15T00:00:00Z');
insert into job (id, title, team, location, employment_type, pay, summary, responsibilities, requirements, status, sort_order, posted_at, updated_at) values ('fulfilment-associate-days-houston-tx', 'Fulfilment Associate (days)', 'Warehouse', 'Houston, TX', 'Hourly', '$19–$22/h', 'Receive, store, pick and pack customer orders in our fulfilment centres.', '["Receive inbound stock and record lots and expiry dates", "Pick and pack orders accurately and on time", "Keep the floor safe and tidy"]'::jsonb, '["Able to lift up to 50 lb and stand for a full shift", "Attention to detail", "Forklift certification is a plus"]'::jsonb, 'OPEN', 40, '2026-09-15T00:00:00Z', '2026-09-15T00:00:00Z');
insert into job (id, title, team, location, employment_type, pay, summary, responsibilities, requirements, status, sort_order, posted_at, updated_at) values ('inventory-control-lead-edison-nj', 'Inventory Control Lead', 'Warehouse', 'Edison, NJ', 'Full-time', '$58k–$70k', 'Receive, store, pick and pack customer orders in our fulfilment centres.', '["Receive inbound stock and record lots and expiry dates", "Pick and pack orders accurately and on time", "Keep the floor safe and tidy"]'::jsonb, '["Able to lift up to 50 lb and stand for a full shift", "Attention to detail", "Forklift certification is a plus"]'::jsonb, 'OPEN', 50, '2026-09-15T00:00:00Z', '2026-09-15T00:00:00Z');
insert into job (id, title, team, location, employment_type, pay, summary, responsibilities, requirements, status, sort_order, posted_at, updated_at) values ('delivery-driver-houston-tx', 'Delivery Driver', 'Delivery', 'Houston, TX', 'Hourly', '$21–$25/h + tips', 'Deliver orders to customers in your city in an AfroTransact vehicle or your own.', '["Run optimised routes with the driver app", "Capture proof of delivery", "Treat every customer’s order with care"]'::jsonb, '["Valid driver’s licence and a clean record", "Smartphone (iOS or Android)", "21 or older"]'::jsonb, 'OPEN', 60, '2026-09-15T00:00:00Z', '2026-09-15T00:00:00Z');
