insert into job (id, title, team, location, employment_type, pay, summary, responsibilities, requirements, status, sort_order, posted_at, updated_at) values ('seller-success-manager-remote-us', 'Seller Success Manager', 'Sales', 'Remote (US)', 'Full-time', '$75k–$95k', 'Help sellers launch and grow their shops on AfroTransact.', '["Onboard new sellers and set them up for success", "Run account reviews and growth plans", "Bring seller feedback to product"]'::jsonb, '["3+ years in account management or seller success", "Comfortable with data and spreadsheets", "Ties to diaspora business communities"]'::jsonb, 'OPEN', 80, '2026-09-15T00:00:00Z', '2026-09-15T00:00:00Z');
